# Тикет -- https://erp.dinord.ru/app/issue/ISS-2025-01841
if doc.reference_type == 'Workflow Task' and doc.allocated_to:
    task = frappe.get_cached_doc("Workflow Task", doc.reference_name)
    
    is_rejected = any(
        row.get("state") == "Отклонено" 
        for row in task.get("available_workflow_transitions", [])
    )
    needs_approval = any(
        row.get("action") == "Согласовано"
        for row in task.get("available_workflow_transitions", [])
    )
    
    if is_rejected:
        doc.run_trigger("workflow_rejection_notification")
    elif needs_approval:
        doc.run_trigger("workflow_approval_notification")

# 1. Получаем согласованные оценки
approved_estimations = []
for estimation in doc.estimations:
    if estimation.status == "Согласовано":
        approved_estimations.append(estimation)

if not approved_estimations:
    # Нет согласованных оценок - выходим
    pass
else:
    # 2. Получаем список праздников и коротких дней
    holiday_list = frappe.db.get_value("Project", doc.project, "holiday_list")
    holidays = []
    if holiday_list:
        holiday_records = frappe.db.get_all("Holiday", 
                                         filters={"parent": holiday_list},
                                         fields=["holiday_date"])
        for holiday in holiday_records:
            holidays.append(frappe.utils.getdate(holiday.holiday_date))
    
    # Получаем данные о коротких рабочих днях
    short_days = {}
    working_hours_on_date = frappe.db.get_value("Project", doc.project, "custom_working_hours_on_date")
    if working_hours_on_date:
        short_days_records = frappe.db.get_all("Working Hours Table", 
                                            filters={"parent": working_hours_on_date},
                                            fields=["wht_date", "wht_hours"])
        for record in short_days_records:
            short_days[frappe.utils.getdate(record.wht_date)] = frappe.utils.flt(record.wht_hours)

    # 3. Обрабатываем каждую оценку
    for estimation in approved_estimations:
        # Базовые данные
        project_role = estimation.project_role
        task = estimation.task
        if not task:
            task_record = frappe.db.get_value("Task", {"custom_linked_issue": doc.name}, "name")
            if task_record:
                task = task_record
        
        grade = frappe.utils.flt(estimation.grade)
        
        if not task and not project_role:
            frappe.throw("Не указана задача или роль проекта")

        # Даты периода
        start_date = frappe.utils.getdate(doc.opening_date)
        if doc.custom_expected_resolution_date:
            end_date = frappe.utils.getdate(doc.custom_expected_resolution_date)
        else:
            end_date = start_date

        # 4. Работа с Project Work Effort (с ignore_permissions)
        pwe_filters = {
            "pwe_project": doc.project,
            "pwe_task": task,
            "pwe_project_role": project_role
        }
        
        pwe_exists = frappe.db.exists("Project Work Efforts", pwe_filters)
        if pwe_exists:
            pwe = frappe.get_doc("Project Work Efforts", pwe_filters, ignore_permissions=True)
            # Получаем текущие данные
            current_data = []
            for row in pwe.pwe_amount:
                current_data.append({
                    "year": int(row.pwea_year),
                    "month": int(row.pwea_month),
                    "hours": frappe.utils.flt(row.pwea_plan, 2)
                })
        else:
            pwe = frappe.new_doc("Project Work Efforts")
            pwe.update(pwe_filters)
            current_data = []

        # 5. Рассчитываем новые данные только если нужно
        if not pwe_exists or current_data:
            # Расчет рабочих дней и часов
            months = []
            current_month = frappe.utils.get_first_day(start_date)
            last_month = frappe.utils.get_last_day(end_date)
            
            while current_month <= last_month:
                months.append({
                    "year": current_month.year,
                    "month": current_month.month,
                    "start": max(frappe.utils.get_first_day(current_month), start_date),
                    "end": min(frappe.utils.get_last_day(current_month), end_date)
                })
                # Переход к следующему месяцу
                if current_month.month == 12:
                    current_month = current_month.replace(year=current_month.year+1, month=1, day=1)
                else:
                    current_month = current_month.replace(month=current_month.month+1, day=1)

            # Считаем рабочие часы по месяцам
            working_hours_by_month = {}
            total_hours = 0
            
            for month in months:
                month_key = str(month['year']) + "-" + str(month['month'])
                working_hours_by_month[month_key] = 0
                
                current_day = month["start"]
                while current_day <= month["end"]:
                    if current_day.weekday() < 5:  # Пн-Пт
                        is_holiday = False
                        for h in holidays:
                            if h == current_day:
                                is_holiday = True
                                break
                        
                        if not is_holiday:
                            # Проверяем, является ли день коротким
                            day_hours = 8  # стандартный рабочий день
                            if current_day in short_days:
                                day_hours = short_days[current_day]
                            
                            # Обновляем значения
                            working_hours_by_month[month_key] = working_hours_by_month.get(month_key, 0) + day_hours
                            total_hours = total_hours + day_hours
                    
                    current_day = frappe.utils.add_days(current_day, 1)

            # Подготавливаем данные для сохранения
            new_data = []
            if total_hours > 0:
                for month_key in working_hours_by_month:
                    month_hours = working_hours_by_month[month_key]
                    if month_hours > 0:
                        year_month = month_key.split("-")
                        year = int(year_month[0])
                        month = int(year_month[1])
                        hours = frappe.utils.flt((grade * month_hours) / total_hours, 2)
                        new_data.append({
                            "year": year,
                            "month": month,
                            "hours": hours
                        })

            # 6. Сравниваем данные
            needs_update = not pwe_exists  # Новый документ всегда нужно сохранять
            
            if pwe_exists:
                if len(current_data) != len(new_data):
                    needs_update = True
                else:
                    for i in range(len(current_data)):
                        curr = current_data[i]
                        new = new_data[i]
                        if (curr["year"] != new["year"] or 
                            curr["month"] != new["month"] or 
                            abs(curr["hours"] - new["hours"]) > 0.0001):
                            needs_update = True
                            break

            # 7. Сохраняем только при изменениях (с ignore_permissions)
            if needs_update:
                if pwe_exists:
                    pwe.set("pwe_amount", [])
                
                for month in new_data:
                    pwe.append("pwe_amount", {
                        "pwea_year": month["year"],
                        "pwea_month": month["month"],
                        "pwea_plan": month["hours"],
                        "pwea_expected": month["hours"]
                    })
                
                pwe.save(ignore_permissions=True)

if doc.status in ['Resolved', 'Closed']:
    doc.custom_is_overdue = 0

# Если дата не установлена - просрочки нет  
elif not doc.custom_expected_resolution_date:
    doc.custom_is_overdue = 0

# Сравниваем даты
else:  
    current_date = frappe.utils.getdate()  # datetime.date объект  
    expected_date = frappe.utils.getdate(doc.custom_expected_resolution_date)  # Преобразуем в datetime.date  
    doc.custom_is_overdue = 1 if expected_date < current_date else 0
